class Solution { public int[] getBiggestThree(int[][] grid) { int m = grid.length, n = grid[0].length; java.util.TreeSet<Integer> top = new java.util.TreeSet<>(); for (int i = 0; i < m; i++) { for (int j = 0; j < n; j++) { int maxD = Math.min(Math.min(i, m - 1 - i), Math.min(j, n - 1 - j)); for (int d = 0; d <= maxD; d++) { int sum; if (d == 0) { sum = grid[i][j]; } else { sum = 0; int r = i - d, c = j; for (int k = 0; k < d; k++) { sum += grid[r][c]; r++; c++; } for (int k = 0; k < d; k++) { sum += grid[r][c]; r++; c--; } for (int k = 0; k < d; k++) { sum += grid[r][c]; r--; c--; } for (int k = 0; k < d; k++) { sum += grid[r][c]; r--; c++; } } top.add(sum); if (top.size() > 3) top.pollFirst(); } } } int[] res = new int[top.size()]; int idx = res.length - 1; for (int v : top) res[idx--] = v; return res; } }